"""Build ``generated/compose.dashboard.yaml`` text."""

from raft.core.core.config.settings.dashboard_config import (
    DASHBOARD_SERVICE_NAME,
    DashboardConfig,
)


class DashboardComposeYaml:
    """Compose fragment for the always-on dashboard service (or empty)."""

    def build(self, cfg: DashboardConfig) -> str:
        if not cfg.enabled:
            return self._empty()
        return "\n".join(self._service_lines(cfg)) + "\n"

    @staticmethod
    def _empty() -> str:
        return (
            "# Generated by `raft render` — always-on dashboard (disabled).\n"
            "services: {}\n"
        )

    def _service_lines(self, cfg: DashboardConfig) -> list[str]:
        port = cfg.port
        name = DASHBOARD_SERVICE_NAME
        return [
            "# Generated by `raft render` — always-on raft-dashboard.",
            "services:",
            f"  {name}:",
            *self._build_block(),
            *self._runtime_block(cfg, port),
            *self._volume_block(),
            *self._resources_block(),
        ]

    @staticmethod
    def _build_block() -> list[str]:
        return [
            "    build:",
            "      context: ./dashboard",
            "    working_dir: /raft",
            '    user: "${RAFT_HOST_UID:-0}:${RAFT_HOST_GID:-0}"',
            "    group_add:",
            '      - "${RAFT_DOCKER_GID:-0}"',
        ]

    def _runtime_block(self, cfg: DashboardConfig, port: int) -> list[str]:
        lines = [
            "    environment:",
            "      RAFT_DATA_HOME: /raft",
            # nginx listens on dashboard.port; uvicorn stays on loopback inside.
            f'      RAFT_SERVE_PORT: "{port}"',
            '      RAFT_DASHBOARD_APP_PORT: "18787"',
            # Absolute host home for Settings → Update (Docker one-shot + identity).
            '      RAFT_HOST_HOME: "${RAFT_HOST_HOME}"',
            *self._oauth_env_file(cfg),
            "    ports:",
            f'      - "127.0.0.1:{port}:{port}"',
        ]
        return lines

    @staticmethod
    def _oauth_env_file(cfg: DashboardConfig) -> list[str]:
        if cfg.auth.mode != "oauth":
            return []
        return [
            "    env_file:",
            "      - ./secrets/dashboard/oauth.env",
        ]

    def _volume_block(self) -> list[str]:
        return [
            "    volumes:",
            *self._host_volumes(),
            *self._data_home_volumes(),
            "    restart: unless-stopped",
        ]

    @staticmethod
    def _host_volumes() -> list[str]:
        return [
            "      - /var/run/docker.sock:/var/run/docker.sock",
            # Host uv-tool env (read-only) so Update can verify the host CLI.
            '      - "${RAFT_HOST_HOME}/.local:${RAFT_HOST_HOME}/.local:ro"',
        ]

    @staticmethod
    def _data_home_volumes() -> list[str]:
        return [
            "      - .:/raft:ro",
            "      - ./settings.yaml:/raft/settings.yaml",
            "      - ./state/locks:/raft/state/locks",
            "      - ./state/firewall:/raft/state/firewall",
            "      - ./state/alerts:/raft/state/alerts",
            "      - ./state/serve:/raft/state/serve",
            "      - ./state/events:/raft/state/events",
            "      - ./state/metrics:/raft/state/metrics",
            "      - ./state/service-logs:/raft/state/service-logs",
            "      - ./state/scaling:/raft/state/scaling",
            "      - ./state/acme:/raft/state/acme",
            "      - ./certs:/raft/certs",
            "      - ./secrets:/raft/secrets",
            "      - ./generated:/raft/generated",
        ]

    @staticmethod
    def _resources_block() -> list[str]:
        return [
            "    deploy:",
            "      resources:",
            "        limits:",
            '          cpus: "0.50"',
            "          memory: 256M",
            "        reservations:",
            '          cpus: "0.05"',
            "          memory: 64M",
        ]
